// Groq-Whisper acepta .ogg pero no la extensión .oga que usa Telegram.
// Solo se renombra el archivo: el audio sigue en la propiedad binaria "data", en memoria.
for (const item of $input.all()) {
  const b = item.binary && item.binary.data;
  if (b) {
    b.fileName = (b.fileName || 'nota_de_voz').replace(/\.oga$/i, '') .replace(/\.ogg$/i, '') + '.ogg';
    b.mimeType = 'audio/ogg';
  }
}
return $input.all();

// Base de conocimiento de NEXA DIGITAL (editá estos textos con la info real de la agencia)
const docs = [
  'NEXA DIGITAL es una agencia de marketing digital para pymes y emprendimientos de Chile. Ayuda a conseguir clientes por internet con estrategia, contenido y publicidad.',
  'Servicios: plan de marketing digital, gestión de redes sociales (Instagram, Facebook, TikTok), publicidad en Meta Ads y Google Ads, diseño de tiendas online y sitios web, y estrategias para turismo como cabañas y alojamientos.',
  'Cómo trabajamos: 1) conversación inicial gratuita, 2) diagnóstico del negocio, 3) propuesta con plan y presupuesto, 4) ejecución y reportes mensuales de resultados.',
  'Precios: cada plan se cotiza según el diagnóstico, el alcance y el presupuesto del cliente. Un asesor comercial confirma el valor final; el asistente no entrega precios cerrados.',
  'Plazos: la propuesta se envía dentro de 48 horas hábiles después del diagnóstico. Las campañas de publicidad pueden comenzar en una semana desde la aprobación.',
  'Atención: lunes a viernes de 9:00 a 18:00 (hora de Chile). Fuera de ese horario, el asistente de voz registra la consulta y un asesor contacta al cliente el siguiente día hábil.',
];
return docs.map((texto, i) => ({ json: { id: i + 1, texto } }));

// COMPLIANCE - DESTRUCCIÓN BINARIA
// Se descartan TODOS los payloads binarios (nota de voz del cliente y audio TTS).
// Solo sobreviven metadatos mínimos, sin audio, para la auditoría.
let respuesta = '';
let estado = 'contingencia_audio_no_valido';
try {
  respuesta = $('Contención 200 caracteres').first().json.respuesta;
  estado = 'respondido_por_voz';
} catch (e) {}

const msg = $('Telegram Trigger').first().json.message || {};
let transcripcion = '';
try { transcripcion = $('Whisper STT (Groq gratis)').first().json.text || ''; } catch (e) {}

// Se devuelven items SOLO con json: n8n no propaga ninguna propiedad "binary".
return [{
  json: {
    chat_id: msg.chat ? msg.chat.id : null,
    duracion_audio_seg: msg.voice ? msg.voice.duration : null,
    transcripcion,
    respuesta,
    caracteres_tts: respuesta.length,
    estado,
    binarios_destruidos: true,
    procesado: $now.toISO(),
  },
}];

